TemplateBody:
AWSTemplateFormatVersion: "2010-09-09"
Description: CashSense Bill Reminder Infrastructure (Lambda only - FIXED SNS message format)

Parameters:
  BillsTableName:
    Type: String
    Default: CashSenseBills
    Description: Existing DynamoDB table name for bills
  IosPlatformApplicationArn:
    Type: String
    Description: Existing SNS iOS PlatformApplication ARN
  DeviceRegistryTableName:
    Type: String
    Default: CashSense-DeviceRegistry
    Description: Existing Device Registry DynamoDB table name
  AutoRolloverOverdue:
    Type: String
    Default: "false"
    AllowedValues: ["true", "false"]

Resources:
  SchedulerRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: CashSenseSchedulerPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:Scan
                  - dynamodb:GetItem
                  - dynamodb:UpdateItem
                Resource: !Sub "arn:aws:dynamodb:${AWS::Region}:${AWS::AccountId}:table/${BillsTableName}"
              - Effect: Allow
                Action:
                  - sns:CreateTopic
                  - sns:Publish
                Resource: "*"
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: "*"

  BillReminderScheduler:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: CashSense-ScheduleBillReminder
      Runtime: nodejs20.x
      Handler: index.handler
      Role: !GetAtt SchedulerRole.Arn
      Timeout: 30
      MemorySize: 256
      Environment:
        Variables:
          BILLS_TABLE: !Ref BillsTableName
          IOS_PLATFORM_APP_ARN: !Ref IosPlatformApplicationArn
          DEVICE_REGISTRY_TABLE: !Ref DeviceRegistryTableName
          AWS_ACCOUNT_ID: !Ref AWS::AccountId
          AUTO_ROLLOVER_OVERDUE: !Ref AutoRolloverOverdue
          OVERDUE_ROLLOVER_GRACE_MIN: "1440"
      Code:
        ZipFile: |
          const { DynamoDBClient } = require("@aws-sdk/client-dynamodb");
          const { DynamoDBDocumentClient, ScanCommand, UpdateCommand } = require("@aws-sdk/lib-dynamodb");
          const { SNSClient, CreateTopicCommand, PublishCommand } = require("@aws-sdk/client-sns");

          const dynamoClient = new DynamoDBClient({});
          const dynamo = DynamoDBDocumentClient.from(dynamoClient);
          const sns = new SNSClient({});

          const BILLS_TABLE = process.env.BILLS_TABLE;
          const AUTO_ROLLOVER_OVERDUE = (process.env.AUTO_ROLLOVER_OVERDUE || "false") === "true";
          const OVERDUE_ROLLOVER_GRACE_MIN = Number(process.env.OVERDUE_ROLLOVER_GRACE_MIN || 1440);

          function addMonthsClamped(dateIso, months, anchorDay) {
            const d = new Date(dateIso);
            const year = d.getUTCFullYear();
            const month = d.getUTCMonth() + months;
            const first = new Date(Date.UTC(year, month, 1, d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds()));
            const targetYear = first.getUTCFullYear();
            const targetMonth = first.getUTCMonth();
            const lastDay = new Date(Date.UTC(targetYear, targetMonth + 1, 0)).getUTCDate();
            const day = Math.min(anchorDay, lastDay);
            return new Date(Date.UTC(targetYear, targetMonth, day, d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds())).toISOString();
          }

          function computeNextDueAt(bill) {
            const interval = Math.max(1, Number((bill.recurrence && bill.recurrence.interval) || 1));
            const cur = new Date(bill.dueAt);
            if (bill.recurrence && bill.recurrence.frequency === "WEEKLY") {
              return new Date(cur.getTime() + interval * 7 * 24 * 60 * 60 * 1000).toISOString();
            }
            if (bill.recurrence && bill.recurrence.frequency === "MONTHLY") {
              const anchor = Number(bill.anchorDayOfMonth || cur.getUTCDate());
              return addMonthsClamped(bill.dueAt, interval, anchor);
            }
            return null;
          }

          async function ensureUserTopic(userId) {
            const topicName = `CashSense-User-${userId}`;
            const command = new CreateTopicCommand({ Name: topicName });
            const response = await sns.send(command);
            return response.TopicArn;
          }

          async function publishBillPush(userId, bill) {
            try {
              const topicArn = await ensureUserTopic(userId);
              const payload = {
                aps: { 
                  alert: { 
                    title: "Bill Due Reminder", 
                    body: `${bill.name} is due soon` 
                  }, 
                  sound: "default" 
                },
                billId: bill.billId,
                cycle: bill.cycle || 1,
                dueAt: bill.dueAt,
              };

              const apnsPayload = JSON.stringify(payload);

              const command = new PublishCommand({
                TopicArn: topicArn,
                MessageStructure: "json",
                Message: JSON.stringify({
                  default: `${bill.name} is due soon`,
                  APNS: apnsPayload,
                  APNS_SANDBOX: apnsPayload,
                }),
              });

              await sns.send(command);
              console.log(`? Push sent for bill ${bill.billId} to user ${userId}`);
            } catch (error) {
              console.error(`? Failed to send push for bill ${bill.billId}:`, error);
            }
          }

          exports.handler = async () => {
            try {
              console.log(`? Starting bill reminder check at ${new Date().toISOString()}`);
              console.log(`? Scanning table: ${BILLS_TABLE}`);

              const now = new Date();
              const scanCommand = new ScanCommand({ TableName: BILLS_TABLE });
              const scan = await dynamo.send(scanCommand);
              const items = scan.Items || [];

              console.log(`? Found ${items.length} bills`);

              let notificationsSent = 0;
              let rollsProcessed = 0;

              for (const bill of items) {
                if (!bill.dueAt) {
                  console.log(`?? Bill ${bill.billId} has no dueAt, skipping`);
                  continue;
                }

                const due = new Date(bill.dueAt);
                const remindMin = Number(bill.remindMinutesBefore || 60);
                const remindAt = new Date(due.getTime() - remindMin * 60 * 1000);

                console.log(`? Bill: ${bill.name} (${bill.billId})`);
                console.log(`   Due: ${bill.dueAt}`);
                console.log(`   Remind at: ${remindAt.toISOString()}`);
                console.log(`   Notified: ${bill.notified || false}`);
                console.log(`   Paid: ${bill.paid || false}`);

                // Send reminder if within reminder window
                if (!bill.notified && now >= remindAt && now <= due) {
                  console.log(`? Sending reminder for ${bill.name}`);
                  await publishBillPush(bill.userId, bill);

                  const updateCommand = new UpdateCommand({
                    TableName: BILLS_TABLE,
                    Key: { userId: bill.userId, billId: bill.billId },
                    UpdateExpression: "SET notified = :t",
                    ExpressionAttributeValues: { ":t": true },
                  });
                  await dynamo.send(updateCommand);
                  notificationsSent++;
                }

                // Auto-rollover if overdue and unpaid
                if (AUTO_ROLLOVER_OVERDUE && bill.recurrence && bill.recurrence.frequency && !bill.paid) {
                  if (now.getTime() > due.getTime() + OVERDUE_ROLLOVER_GRACE_MIN * 60 * 1000) {
                    const next = computeNextDueAt(bill);
                    if (next) {
                      console.log(`? Rolling over ${bill.name} from ${bill.dueAt} to ${next}`);
                      const updateCommand = new UpdateCommand({
                        TableName: BILLS_TABLE,
                        Key: { userId: bill.userId, billId: bill.billId },
                        UpdateExpression:
                          "SET dueAt = :due, paid = :paid, notified = :notified, cycle = if_not_exists(cycle, :one) + :one, lastRolledAt = :rolled",
                        ExpressionAttributeValues: {
                          ":due": next,
                          ":paid": false,
                          ":notified": false,
                          ":rolled": now.toISOString(),
                          ":one": 1,
                        },
                      });
                      await dynamo.send(updateCommand);
                      rollsProcessed++;
                    }
                  }
                }
              }

              const summary = {
                ok: true,
                timestamp: now.toISOString(),
                checked: items.length,
                notificationsSent,
                rollsProcessed
              };

              console.log(`? Completed:`, summary);
              return summary;

            } catch (error) {
              console.error(`? Lambda error:`, error);
              throw error;
            }
          };

  ScheduleRule:
    Type: AWS::Events::Rule
    Properties:
      Name: CashSenseBillReminderSchedule
      ScheduleExpression: rate(5 minutes)
      State: ENABLED
      Targets:
        - Arn: !GetAtt BillReminderScheduler.Arn
          Id: BillReminderSchedulerTarget

  PermissionForEventsToInvokeLambda:
    Type: AWS::Lambda::Permission
    Properties:
      FunctionName: !Ref BillReminderScheduler
      Action: lambda:InvokeFunction
      Principal: events.amazonaws.com
      SourceArn: !GetAtt ScheduleRule.Arn

Outputs:
  BillsTableName:
    Value: !Ref BillsTableName
  SchedulerFunctionName:
    Value: !Ref BillReminderScheduler
